import type { FoleyManifest } from "@/lib/types";

export interface DemoVideoPreset {
  id: "demo1" | "demo2";
  label: string;
  sublabel: string;
  videoUrl: string;
  note: string;
}

/**
 * Fallback quick-load presets (FR-1).
 * Videos are local offline renders under /video/*.mp4 (generated by
 * backend/generate_demo_videos.py) so Demo Mode works fully offline.
 * (Remote alternatives: ForBiggerBlazes / ForBiggerEscapes from the
 * Google sample bucket — kept out of the hot path for offline use.)
 * Audio is fully local under /audio/*.wav. Uploads replace these entirely.
 */
export const DEMO_VIDEO_PRESETS: DemoVideoPreset[] = [
  {
    id: "demo1",
    label: "Demo 1: Sci-Fi Walk",
    sublabel: "Striding concrete steps + scifi hum",
    videoUrl: "/video/demo1-sci-fi-walk.mp4",
    note: "15s offline render, footstep-driven.",
  },
  {
    id: "demo2",
    label: "Demo 2: Combat Impact",
    sublabel: "Sword swooshes, clangs + booms",
    videoUrl: "/video/demo2-combat-impact.mp4",
    note: "15s offline render, impact-driven.",
  },
];

export function getPresetVideoUrl(id: "demo1" | "demo2"): string {
  return DEMO_VIDEO_PRESETS.find((p) => p.id === id)?.videoUrl ?? DEMO_VIDEO_PRESETS[1].videoUrl;
}

